True def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Each top-row marker is the apex of a downward, widening triangle.
    for x, value in enumerate(grid[0]):
        if value == 0:
            continue
        for r in range(h):
            left, right = x - r, x + r
            for c in range(max(0, left + 1), min(w, right)):
                if out[r][c] == 0:
                    out[r][c] = 2
    return out
